from docx import Document

docx_path = "/Data2/v-weilinjin/workshop/AttributeBench/benchmarks/GAIA/2023/validation/cffe0e32-c9a6-4c52-9877-78ceb4aaa9fb.docx"
document = Document(docx_path)

# Employees 2-13
employee_names = []
for i in range(2, 14):
    name = document.paragraphs[i].text.strip()
    if name:
        employee_names.append(name)

# Profiles 21-32
profiles = {}
for i in range(21, 33):
    line = document.paragraphs[i].text.strip()
    if ":" in line:
        name, interests = line.split(":", 1)
        profiles[name.strip()] = [x.strip() for x in interests.split(",")]

# Gifts 36-46
gifts = []
for i in range(36, 47):
    gift = document.paragraphs[i].text.strip()
    if gift:
        gifts.append(gift)

print("Employees:")
for n in employee_names:
    print(n)
print("\nProfiles:")
for n, ints in profiles.items():
    print(n, ints)
print("\nGifts:")
for g in gifts:
    print(g)
